import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

class AirportSimulation {
    private final Semaphore runway = new Semaphore(1, true);
    private final Semaphore grounds = new Semaphore(3, true);
    private final Semaphore gates = new Semaphore(3, true);
    private final Semaphore fuelTruck = new Semaphore(1, true);
    private final AtomicInteger planesServed = new AtomicInteger(0);
    private final LongAdder totalWaitTime = new LongAdder();

    class Plane implements Runnable {
        int id; boolean isEmergency;
        Plane(int id, boolean isEmergency) { this.id = id; this.isEmergency = isEmergency; }

        public void run() {
            long start = System.currentTimeMillis();
            try {
                System.out.println("Plane " + id + (isEmergency ? " (EMERGENCY)" : "") + " requesting landing.");
                grounds.acquire(); // Max 3 on ground
                runway.acquire();  // Needs runway
                System.out.println("Plane " + id + " landing.");
                Thread.sleep(500); 
                runway.release();

                gates.acquire();
                System.out.println("Plane " + id + " docked at gate.");

                // Concurrent disembark/embark and cleaning
                Thread t1 = new Thread(() -> { try { Thread.sleep(1000); } catch (Exception e) {} });
                Thread t2 = new Thread(() -> { try { Thread.sleep(1000); } catch (Exception e) {} });
                t1.start(); t2.start();

                fuelTruck.acquire();
                System.out.println("Plane " + id + " refuelling exclusively.");
                Thread.sleep(1000);
                fuelTruck.release();

                t1.join(); t2.join();

                runway.acquire();
                System.out.println("Plane " + id + " taking off.");
                Thread.sleep(500);
                gates.release();
                runway.release();
                grounds.release();

                planesServed.incrementAndGet();
                totalWaitTime.add(System.currentTimeMillis() - start);
                System.out.println("Plane " + id + " departed.");
            } catch (InterruptedException e) { e.printStackTrace(); }
        }
    }

    void start() {
        ExecutorService exec = Executors.newCachedThreadPool();
        // Congested scenario
        exec.execute(new Plane(1, false)); // Gate 1
        exec.execute(new Plane(2, false)); // Gate 2
        try { Thread.sleep(100); } catch (Exception e) {}
        exec.execute(new Plane(3, false)); // Waiting for gate
        exec.execute(new Plane(4, false)); // Waiting for ground
        exec.execute(new Plane(99, true)); // Emergency

        exec.shutdown();
        try { exec.awaitTermination(1, TimeUnit.MINUTES); } catch (Exception e) {}
        System.out.println("--- Statistics ---");
        System.out.println("Planes Served: " + planesServed.get());
        System.out.println("Average Process Time: " + (totalWaitTime.sum() / Math.max(1, planesServed.get())) + "ms");
    }

    public static void main(String[] args) { new AirportSimulation().start(); }
}
